            var migrationDriver = new MigrateSession(loggerMock.Object);
            var clientMock = new Mock<IClient>();
            clientMock.Setup(c => c.SetSlotRange(It.IsAny<byte[]>(), It.IsAny<string>(), It.IsAny<SlotRange[]>()))
